mapper.select:
SELECT ja.id, ja.candidate_id, r.file_name AS resume_file_name, screening.overall_match_score AS ai_screening_score, screening.recommendation AS ai_recommendation, ja.status, ja.created_at FROM job_applications ja LEFT JOIN resumes r ON r.id = ja.resume_id LEFT JOIN LATERAL ( SELECT overall_match_score, recommendation FROM application_ai_screenings WHERE application_id = ja.id AND status = 'COMPLETED' ORDER BY created_at DESC, id DESC LIMIT 1 ) screening ON TRUE WHERE ja.is_deleted = false AND ja.job_id = #{jobId} AND ja.enterprise_id = #{enterpriseId}
AND ja.status = #{status}
ORDER BY ja.created_at
ASC DESC
